15	Server Action	ir.actions.server	\N	16	form	<?xml version="1.0"?>\n<form string="Server Action">\n                    <header>\n                        <field name="binding_model_id" invisible="1"/>\n                        <button name="create_action" string="Create Contextual Action" type="object" class="btn-primary" attrs="{'invisible':[('binding_model_id','!=',False)]}" help="Display an option in the 'More' top-menu in order to run this action."/>\n                        <button name="unlink_action" string="Remove Contextual Action" type="object" attrs="{'invisible':[('binding_model_id','=',False)]}" help="Remove 'More' top-menu contextual action related to this action"/>\n                        <button name="run" string="Run" type="object" class="btn-primary" attrs="{'invisible':['|', ('model_id', '!=', 23), ('state', '!=', 'code')]}" help="Run this action manually."/>\n                    </header>\n                    <sheet>\n                        <div class="oe_title">\n                            <label for="name"/>\n                            <h1><field name="name" placeholder="e.g. Update order quantity"/></h1>\n                        </div>\n                        <group name="action_wrapper">\n                            <group name="action_content">\n                                <field name="model_id" options="{'no_create': True}"/>\n                                <field name="model_name" invisible="1"/>\n                            </group>\n                            <group>\n                                <field name="state"/>\n                                <field name="type" invisible="1"/>\n                                <field name="crud_model_id" options="{'no_create': True}" attrs="{'invisible': [('state', '!=', 'object_create')], 'required': [('state', '=', 'object_create')]}"/>\n                                <field name="crud_model_name" invisible="1"/>\n                                <field name="link_field_id" domain="[('model_id', '=', model_id), ('relation', '=', crud_model_name),                                     ('ttype', 'in', ['many2one', 'one2many', 'many2many'])]" attrs="{'invisible': [('state', '!=', 'object_create')]}" context="{'default_model_id': model_id, 'default_relation': crud_model_name}"/>\n                            </group>\n                        </group>\n                        <notebook>\n                            <page string="Python Code" name="code" autofocus="autofocus" attrs="{'invisible': [('state', '!=', 'code')]}">\n                                <field name="code" widget="ace" options="{'mode': 'python'}" placeholder="Enter Python code here. Help about Python expression is available in the help tab of this document."/>\n                            </page>\n\n                            <page string="Data to Write" name="page_object" autofocus="autofocus" attrs="{'invisible':[('state', 'not in', ['object_create', 'object_write'])]}">\n                                <p attrs="{'invisible': [('model_id', '!=', False)]}">\n                                    Please set the Model to Create before choosing values\n                                </p>\n                                <field name="fields_lines">\n                                     <tree string="Field Mappings" editable="bottom">\n                                        <field name="col1" options="{'no_create': True}" domain="['|', ('model_id', '=', parent.crud_model_id), ('model_id', '=', parent.model_id)]"/>\n                                        <field name="evaluation_type"/>\n                                        <field name="resource_ref" options="{'hide_model': True, 'no_create': True}" attrs="{'readonly': [('evaluation_type', '!=', 'reference')]}"/>\n                                        <field name="value" attrs="{'readonly': [('evaluation_type', '=', 'reference')]}" options="{'no_create': True}" force_save="1"/>\n                                    </tree>\n      